+    }
+    let project = |p: Point2| ((p.x - a.x) * dx + (p.y - a.y) * dy) / len;
+    let on_line = |p: Point2| ((p.x - a.x) * dy - (p.y - a.y) * dx).abs() <= LEAN_SLACK * len;
